
// tickets.js
'use strict';
let activeSupportTicket='',ticketRequestPending=false;
function ticketEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function ticketRequest(path='',body){const response=await fetch('/api/tickets'+path,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}),data=await response.json();if(!response.ok)throw Error(data.error||'Support unavailable.');return data;}
async function renderSupportTickets(){const container=document.getElementById('supportTicketsContent');if(!container||ticketRequestPending)return;ticketRequestPending=true;const staff=container.dataset.staff==='true';try{if(activeSupportTicket){const data=await ticketRequest('?id='+encodeURIComponent(activeSupportTicket)),ticket=data.ticket;container.innerHTML='<button class="button secondary" data-ticket-back>← TICKETS</button><section class="ticket-detail"><div class="ticket-heading"><span class="ticket-category">'+ticketEscape(ticket.category)+'</span><h2>'+ticketEscape(ticket.title)+'</h2><b class="ticket-status">'+ticketEscape(ticket.status)+'</b></div>'+data.messages.map(m=>'<article class="ticket-message '+(m.is_staff?'staff-reply':'')+'"><header><b>'+ticketEscape(m.author_name)+(m.is_staff?' · STAFF':'')+'</b><time>'+new Date(m.created_at).toLocaleString()+'</time></header><p>'+ticketEscape(m.body)+'</p></article>').join('')+(data.canManage&&staff?'<div class="ticket-staff-controls"><label for="ticketStaffStatus">Status</label><select id="ticketStaffStatus">'+['Open','In progress','Resolved'].map(s=>'<option '+(ticket.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select><button class="button" data-ticket-status>SAVE STATUS</button></div>':'')+'<form id="ticketReplyForm"><label for="ticketReplyBody">Reply</label><textarea id="ticketReplyBody" name="body" rows="6" maxlength="20000" required></textarea><button class="button" type="submit">SEND REPLY</button><p id="ticketActionStatus" role="status"></p></form></section>';}else{const data=await ticketRequest(staff?'?queue=staff':'');container.innerHTML='<div class="ticket-list">'+(data.tickets.length?data.tickets.map(t=>'<article class="ticket-row"><div><span class="ticket-category">'+ticketEscape(t.category)+'</span><button class="ticket-open" data-ticket-open="'+t.id+'">'+ticketEscape(t.title)+'</button><time>'+new Date(t.updated_at).toLocaleString()+'</time></div><b class="ticket-status">'+ticketEscape(t.status)+'</b></article>').join(''):'<p>No support tickets yet.</p>')+'</div>'+(!staff?'<section class="ticket-compose"><h3>Create a ticket</h3><form id="ticketCreateForm"><label for="ticketCategory">Request type</label><select id="ticketCategory" name="category"><option>Staff support</option><option>Ban appeal</option></select><label for="ticketTitle">Title</label><input id="ticketTitle" name="title" minlength="3" maxlength="120" required><label for="ticketBody">Describe your request</label><textarea id="ticketBody" name="body" rows="9" maxlength="20000" required></textarea><label class="ticket-error-attachment"><input type="checkbox" name="includeErrors" '+(window.starfallErrorLog?.text()?'checked':'')+'> Include captured error log</label><p class="ticket-privacy-note">Only you and staff can read this ticket. A ban appeal does not automatically change a ban.</p><button class="button" type="submit">SUBMIT TICKET</button><p id="ticketActionStatus" role="status"></p></form></section>':'');}}catch(error){container.innerHTML='<p class="notice">'+ticketEscape(error.message)+'</p>';}finally{ticketRequestPending=false;}}
document.addEventListener('click',async e=>{const open=e.target.closest('[data-ticket-open]');if(open){activeSupportTicket=open.dataset.ticketOpen;renderSupportTickets();}if(e.target.closest('[data-ticket-back]')){activeSupportTicket='';renderSupportTickets();}if(e.target.closest('[data-ticket-status]')){try{await ticketRequest('',{action:'status',ticketId:activeSupportTicket,status:document.getElementById('ticketStaffStatus').value});renderSupportTickets();}catch(error){document.getElementById('ticketActionStatus').textContent=error.message;}}});
document.addEventListener('submit',async e=>{if(!['ticketCreateForm','ticketReplyForm'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const data=await ticketRequest('',form.id==='ticketCreateForm'?{action:'create',category:form.elements.category.value,title:form.elements.title.value,body:form.elements.body.value+(form.elements.includeErrors?.checked&&window.starfallErrorLog?'\n\nERROR LOG\n'+window.starfallErrorLog.text():'')}:{action:'reply',ticketId:activeSupportTicket,body:form.elements.body.value});if(data.id)activeSupportTicket=data.id;renderSupportTickets();}catch(error){document.getElementById('ticketActionStatus').textContent=error.message;}finally{button.disabled=false;}});renderSupportTickets();


// portal.js
function staffCan(node){if(window.staffPermissionNodes)return !!window.staffPermissionNodes[node]&&(node!=='keyReveal'||!!window.staffPermissionNodes.allianceAdmin);return !!window.isGameAdmin||(node==='multihunter'&&!!window.canMultihunt)||(node==='support'&&!!window.canSupport);}
(function(){if(window.staffUiReady)return;window.staffUiReady=true;
const staffParams=new URLSearchParams(location.search);
window.isStaffWorkspace=staffParams.get('staff_workspace')==='1';
if(staffParams.get('legacy_staff')==='1')localStorage.setItem('starfall-legacy-staff-view','1');
window.useLegacyStaffView=localStorage.getItem('starfall-legacy-staff-view')==='1';
if(window.isStaffWorkspace){document.body.classList.add('staff-workspace');if(!localStorage.getItem('starfall-staff-workspace-v1')){const existing=localStorage.getItem('starfall-round-v2');if(existing)localStorage.setItem('starfall-staff-workspace-v1',existing);}}
function applyStaffViewPreference(){const menu=document.getElementById('legacyStaffMenu');if(menu)menu.hidden=!window.isGameAdmin||window.isStaffWorkspace||!window.useLegacyStaffView;const toggle=document.getElementById('staffLegacyToggle');if(toggle){toggle.checked=window.useLegacyStaffView;toggle.onchange=()=>{window.useLegacyStaffView=toggle.checked;localStorage.setItem('starfall-legacy-staff-view',toggle.checked?'1':'0');};}}
function openPortalStaffWorkspace(id){const routes={control:'adminControl',alliances:'adminAlliances',multihunters:'adminMultihunters'};if(!staffCan(({control:'adminControl',alliances:'allianceAdmin',multihunters:'multihunter'})[id])&&!(id==='control'&&staffCan('bank')))return;const frame=document.querySelector('[data-staff-workspace="'+id+'"]');if(frame&&!frame.getAttribute('src'))frame.src='/game?staff_workspace=1&staff_tool='+(id==='control'&&!staffCan('adminControl')?'bank':id)+'#'+routes[id];}
function openStaffHash(){const id=location.hash.slice(1);if(!['control','alliances','multihunters','tickets','users','news','ranks','audit'].includes(id))return;const button=document.querySelector('[data-staff-tab="'+id+'"]');if(button)button.click();}
document.addEventListener('starfall-session-ready',()=>{applyStaffViewPreference();openStaffHash();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-staff-tab]');if(button){location.hash=button.dataset.staffTab;openPortalStaffWorkspace(button.dataset.staffTab);}});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='starfall-staff-height'||!Number.isFinite(e.data.height))return;for(const frame of document.querySelectorAll('[data-staff-workspace]'))if(frame.contentWindow===e.source)frame.style.height=Math.max(600,Math.min(20000,e.data.height))+'px';});
if(window.isStaffWorkspace)setInterval(()=>{if(window.parent!==window)window.parent.postMessage({type:'starfall-staff-height',height:(document.getElementById('page-admin')?.getBoundingClientRect().height||600)+40},location.origin);},1000);
applyStaffViewPreference();
if(window.isGameAdmin)openStaffHash();
})();
"use strict";
async function portalRequest(action,body){const response=await fetch('/api/portal/'+action,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'The portal is unavailable.');return data;}
(async()=>{try{const session=await portalRequest('session');window.staffPermissionNodes=session.user?.staffPermissions||{};window.isGameAdmin=staffCan('adminControl');window.isAccountAdministrator=session.user?.role==='admin';window.isPortalStaff=['admin','support','multihunter'].includes(session.user?.role);window.canMultihunt=staffCan('multihunter');window.canSupport=staffCan('support');applyPortalStaffPermissions();document.dispatchEvent(new CustomEvent('starfall-session-ready'));document.querySelectorAll('button[data-page^="admin"]').forEach(button=>button.hidden=!staffCan(button.dataset.page==='adminAlliances'?'allianceAdmin':button.dataset.page==='adminMultihunters'?'multihunter':'adminControl'));if((window.isGameAdmin||staffCan('allianceAdmin')&&location.hash==='#adminAlliances'||window.canMultihunt&&location.hash==='#adminMultihunters')&&['/game','/game/','/index.html'].includes(location.pathname)&&/^#admin(Alliances|Multihunters|Control|Round|Planets|Ships|State)$/.test(location.hash)&&typeof navigate==='function')navigate(location.hash.slice(1));document.querySelectorAll('[data-profile-link],[data-session-link]').forEach(el=>el.hidden=!session.user);document.querySelectorAll('[data-staff-link]').forEach(el=>el.hidden=!window.isPortalStaff);document.querySelectorAll('[data-register-link]').forEach(el=>el.hidden=!!session.user);initializePortalControls(session);const label=document.getElementById('portalUser');if(label)label.textContent=session.user?'Signed in as '+session.user.username+' · ID '+session.user.accountId:'Commander portal';const login=document.getElementById('portalLoginLink');if(login&&session.user){login.textContent='Continue game';login.href='/game';}const form=document.getElementById('loginForm');if(form){if(session.user){location.replace('/game');return;}const setup=session.setupRequired;document.getElementById('loginHeading').textContent=setup?'Create the administrator':'Welcome back';document.getElementById('loginIntro').textContent=setup?'Set up the initial admin account for this game portal.':'Sign in with your game account to enter Starfall Command.';document.getElementById('loginSubmit').textContent=setup?'Create admin account':'Sign in';if(setup){form.elements.username.value='admin';form.elements.username.readOnly=true;}form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('loginSubmit'),status=document.getElementById('loginStatus');button.disabled=true;status.textContent='';try{await portalRequest(setup?'setup':'login',{username:form.elements.username.value,password:form.elements.password.value});form.elements.password.value='';location.replace('/game');}catch(error){status.textContent=error.message;button.disabled=false;}});}}catch(error){const status=document.getElementById('loginStatus');if(status)status.textContent=error.message;}})();

document.addEventListener('click',async event=>{if(event.target.closest('[data-portal-logout]')){try{await portalRequest('logout',{});location.href='/';}catch(error){alert(error.message);}}});

function applyPortalSkin(skin){if(!['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides','NyanCat','AstraNexus'].includes(skin))skin='Neutral';document.body.dataset.portalSkin=skin;try{sessionStorage.setItem('starfall-portal-session-skin',skin);}catch{}const picker=document.getElementById('portalTheme');if(picker)picker.value=skin;try{if(localStorage.getItem('starfall-remember-theme')!=='false')localStorage.setItem('starfall-portal-skin',skin);else localStorage.removeItem('starfall-portal-skin');}catch{}}
{let skin='Neutral';try{skin=sessionStorage.getItem('starfall-portal-session-skin')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-portal-skin'):null)||skin;const rotate=sessionStorage.getItem('starfall-rotate-portal-themes')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-rotate-portal-themes'):null);if(rotate==='true'&&!['/game','/game/','/index.html'].includes(location.pathname)){const all=['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides','NyanCat','AstraNexus'];skin=all[(all.indexOf(skin)+1)%all.length];}}catch{}applyPortalSkin(skin);}
document.addEventListener('change',event=>{if(event.target.id==='portalTheme'){sessionStorage.setItem('starfall-rotate-portal-themes','false');localStorage.removeItem('starfall-rotate-portal-themes');applyPortalSkin(event.target.value);location.hash='themes';location.reload();}if(event.target.id==='manualShipRace'){const race=event.target.value;document.querySelectorAll('[data-ship-race]').forEach(card=>card.hidden=race!=='all'&&card.dataset.shipRace!==race);}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-preview-race]');if(button)applyPortalSkin(button.dataset.previewRace);});

document.addEventListener('change',event=>{if(event.target.id==='manualStatsRace')document.querySelectorAll('[data-stat-race]').forEach(table=>table.hidden=event.target.value!=='all'&&table.dataset.statRace!==event.target.value);});

async function initializePortalControls(session){document.querySelectorAll('[data-guest-auth]').forEach(el=>el.hidden=!!session.user);document.querySelectorAll('[data-member-auth]').forEach(el=>el.hidden=!session.user);const sidebarIdentity=document.getElementById('sidebarAccountIdentity');if(sidebarIdentity&&session.user)sidebarIdentity.textContent='Signed in as '+session.user.username+' · ID '+session.user.accountId;const register=document.getElementById('registerForm');if(register){if(session.user){register.hidden=true;const notice=document.createElement('p');notice.textContent='You are already signed in. Manage your existing account under User Profile.';register.after(notice);return;}register.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('registerStatus');if(register.elements.password.value!==register.elements.confirmPassword.value){status.textContent='Passwords do not match.';return;}const button=register.querySelector('button');button.disabled=true;try{await portalRequest('register',{username:register.elements.username.value,password:register.elements.password.value});register.reset();location.replace('/profile.html');}catch(error){status.textContent=error.message;button.disabled=false;}});}const profile=document.getElementById('profileForm');if(profile){try{const data=await portalRequest('profile');const themeSelect=document.getElementById('profileTheme');if(themeSelect&&data.allowedThemes){themeSelect.replaceChildren();for(const id of data.allowedThemes){const option=document.createElement('option');option.value=id;option.textContent=({Unimatrix999World:'Unimatrix999 Sovereign',SilverWorld:'Silver Registry',BorgWorld:'Unimatrix Sovereign',UndineWorld:'Fluidic Dominion',LegendaryWorld:'Imperial Legend',UltimateWorld:'Arrakis Ascendant'})[id]||id;themeSelect.append(option);}}document.getElementById('profileIdentity').textContent='Account: '+data.user.username+' · '+portalRankName(data.user.role)+' · Account ID: '+data.user.accountId;document.getElementById('profilePlanet').textContent=data.planet?'Planet: '+data.planet.name+' · '+data.planet.coords:'No planet yet. Continue game to confirm your colonial charter.';profile.elements.displayName.value=data.planet?.username||data.profile.display_name||data.user.username;profile.elements.theme.value=data.profile.theme;profile.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('profile',{displayName:profile.elements.displayName.value,theme:profile.elements.theme.value});applyPortalSkin(profile.elements.theme.value);document.getElementById('profileStatus').textContent='Profile saved.';}catch(error){document.getElementById('profileStatus').textContent=error.message;}});}catch(error){document.getElementById('profileStatus').textContent=error.message;}}if(document.getElementById('staffUsers')){try{const data=await portalRequest('staff'),table=document.createElement('table');table.className='table';const head=document.createElement('tr');for(const label of ['Account','Role','Planet','Assign']){const cell=document.createElement('th');cell.textContent=label;head.append(cell);}table.append(head);for(const user of data.users){const row=document.createElement('tr'),name=document.createElement('td'),role=document.createElement('td'),owned=document.createElement('td'),action=document.createElement('td'),select=document.createElement('select'),button=document.createElement('button');name.textContent=user.username;role.textContent=user.role;owned.textContent=data.planets.filter(p=>p.ownerId===user.id).map(p=>p.name+' · '+p.coords).join(', ')||'Unassigned';for(const p of data.planets.filter(p=>!p.ownerId||p.ownerId===user.id)){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+' · '+p.coords;option.selected=p.ownerId===user.id;select.append(option);}button.textContent='ASSIGN PLANET';button.className='button';button.disabled=!select.options.length;button.addEventListener('click',async()=>{try{await portalRequest('staff-assign',{userId:user.id,planetId:select.value});location.reload();}catch(error){document.getElementById('staffStatus').textContent=error.message;}});action.append(select,button);row.append(name,role,owned,action);table.append(row);}document.getElementById('staffUsers').replaceChildren(table);}catch(error){document.getElementById('staffStatus').textContent=error.message;}document.getElementById('staffResetForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('reset',{confirmation:e.target.elements.confirmation.value});localStorage.removeItem('starfall-round-v2');localStorage.removeItem('starfall-state');localStorage.removeItem('starfall-save');document.getElementById('staffResetStatus').textContent='Round reset. Default planets regenerated.';}catch(error){document.getElementById('staffResetStatus').textContent=error.message;}});}}

const ARTICLE_ICON_PATHS={'Game mechanic update':'<path d="M32 10v44M10 32h44M16 16l32 32M16 48l32-32"/><circle cx="32" cy="32" r="12"/>','Round update':'<circle cx="32" cy="32" r="23"/><path d="M32 15v18l12 8"/>','Stats update':'<path d="M12 52V35h10v17M27 52V23h10v29M42 52V12h10v40"/>','Error update':'<path d="m32 8 26 46H6zM32 24v14m0 7v2"/>','Pauzed and resumed update':'<path d="M10 15h8v34h-8zM24 15h8v34h-8zM40 15l19 17-19 17z"/>'};
function articleIcon(category){return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round" aria-hidden="true">'+(ARTICLE_ICON_PATHS[category]||ARTICLE_ICON_PATHS['Round update'])+'</svg>';}
function articleText(tag,value){const node=document.createElement(tag);node.textContent=value;return node;}
(async()=>{const form=document.getElementById('staffArticleForm');if(form){const cat=document.getElementById('articleCategory'),preview=document.getElementById('articleCategoryIcon');const refresh=()=>{preview.innerHTML=articleIcon(cat.value);preview.setAttribute('aria-label',cat.value);};refresh();cat.addEventListener('change',refresh);form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('staffArticleSubmit'),status=document.getElementById('staffArticleStatus');button.disabled=true;try{const result=await portalRequest('articles',{id:form.elements.namedItem('articleId').value||undefined,title:form.elements.namedItem('title').value,synopsis:form.elements.namedItem('synopsis').value,category:form.elements.namedItem('category').value,body:form.elements.namedItem('body').value});form.reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';refresh();loadStaffArticles();status.replaceChildren(articleText('span','Published. '));const link=articleText('a','Open article →');link.href='/news-article.html?id='+encodeURIComponent(result.id);status.append(link);}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});}const cards=document.getElementById('staffNewsCards')||document.getElementById('portalNewsCards');if(cards){try{const data=await portalRequest('articles');for(const a of data.articles.slice(0,location.pathname==='/news.html'?100:3)){const card=document.createElement('article');card.className='card';card.dataset.newsDate=new Date(a.published_at).toISOString();card.dataset.staffArticle='true';card.dataset.newsCategory=a.category;const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const meta=articleText('span',new Date(a.published_at).toLocaleDateString()+' · '+a.category);meta.className='eyebrow';const link=articleText('a','Read news article →');link.href='/news-article.html?id='+encodeURIComponent(a.id);card.append(icon,meta,articleText('h2',a.title),articleText('p',a.synopsis),link);cards.append(card);}sortAndPinStaffNews(cards);if(cards.id!=='portalNewsCards')document.getElementById('staffPublishedNews').hidden=!data.articles.length;refreshNewsArchivePagination();}catch{cards.textContent='Staff dispatches are temporarily unavailable.';}}const view=document.getElementById('staffArticleView');if(view){try{const id=new URLSearchParams(location.search).get('id');if(!id)throw Error('Select an article from the news archive.');const data=await portalRequest('articles?id='+encodeURIComponent(id)),a=data.article,icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);view.dataset.newsCategory=a.category;view.classList.add('news-themed-article');view.replaceChildren(icon,articleText('span',a.category+' · '+new Date(a.published_at).toLocaleString()),articleText('h1',a.title),articleText('p',a.synopsis));for(const paragraph of a.body.split(/\n\s*\n/)){const p=document.createElement('p');p.style.whiteSpace='pre-wrap';renderArticleFormatting(p,paragraph);view.append(p);}document.title=a.title+' · Starfall Command';}catch(error){view.textContent=error.message;}}})();

function renderArticleFormatting(parent,text){const pattern=/\[(b|i|font=(?:sans-serif|serif|monospace)|size=(?:14|18|24|32))\]([\s\S]*?)\[\/(b|i|font|size)\]/g;let start=0,match;while((match=pattern.exec(text))){parent.append(document.createTextNode(text.slice(start,match.index)));const kind=match[1].split('=')[0];if(kind!==match[3]){parent.append(document.createTextNode(match[0]));}else{const el=document.createElement(kind==='b'?'strong':kind==='i'?'em':'span');if(kind==='font')el.style.fontFamily=match[1].split('=')[1];if(kind==='size')el.style.fontSize=match[1].split('=')[1]+'px';renderArticleFormatting(el,match[2]);parent.append(el);}start=pattern.lastIndex;}parent.append(document.createTextNode(text.slice(start)));}
function formatArticleSelection(tag){const editor=document.getElementById('articleBodyEditor');if(!editor)return;const from=editor.selectionStart,to=editor.selectionEnd,selected=editor.value.slice(from,to)||'Your text',close=tag.split('=')[0],wrapped='['+tag+']'+selected+'[/'+close+']';editor.setRangeText(wrapped,from,to,'select');editor.focus();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-article-format]');if(button)formatArticleSelection(button.dataset.articleFormat);});document.addEventListener('change',e=>{if(e.target.matches('[data-article-font]'))formatArticleSelection('font='+e.target.value);if(e.target.matches('[data-article-size]'))formatArticleSelection('size='+e.target.value);});

async function loadStaffArticles(){const list=document.getElementById('staffArticlesList');if(!list)return;try{const data=await portalRequest('articles');list.replaceChildren();if(!data.articles.length)list.append(articleText('p','No staff articles published yet.'));for(const a of data.articles){const card=document.createElement('article');card.className='staff-article-row';card.dataset.newsCategory=a.category;const icon=document.createElement('span');icon.className='theme-icon';icon.innerHTML=articleIcon(a.category);const title=articleText('h3',a.title),meta=articleText('p',a.category+' · '+new Date(a.published_at).toLocaleString()),button=articleText('button','EDIT');button.type='button';button.className='button';button.addEventListener('click',async()=>{try{const {article}=await portalRequest('articles?id='+encodeURIComponent(a.id)),form=document.getElementById('staffArticleForm');for(const key of ['title','synopsis','category','body'])form.elements.namedItem(key).value=article[key];form.elements.namedItem('articleId').value=article.id;document.getElementById('staffArticleSubmit').textContent='SAVE CHANGES';document.getElementById('articleCategoryIcon').innerHTML=articleIcon(article.category);document.getElementById('staffArticleStatus').textContent='Editing '+article.title;form.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){list.append(articleText('p',error.message));}});const copy=document.createElement('div');copy.append(title,meta);card.append(icon,copy,button);list.append(card);}}catch(error){list.textContent=error.message;}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-staff-tab]');if(tab){document.querySelectorAll('[data-staff-section]').forEach(section=>section.hidden=section.dataset.staffSection!==tab.dataset.staffTab);document.querySelectorAll('[data-staff-tab]').forEach(button=>button.classList.toggle('active',button===tab));}if(e.target.id==='staffNewArticle'){document.getElementById('staffArticleForm').reset();document.getElementById('staffArticleSubmit').textContent='PUBLISH ARTICLE';document.getElementById('staffArticleStatus').textContent='New article';}});loadStaffArticles();

function sortAndPinStaffNews(cards){const now=Date.now();for(const card of cards.children){const age=now-Date.parse(card.dataset.newsDate||''),pinned=card.dataset.staffArticle==='true'&&age>=0&&age<86400000;card.classList.toggle('staff-news-pinned',pinned);card.dataset.pinned=pinned?'true':'false';let badge=card.querySelector('.staff-pin-badge');if(pinned&&!badge){badge=articleText('span','★ PINNED · FIRST 24 HOURS');badge.className='staff-pin-badge';card.prepend(badge);}if(!pinned&&badge)badge.remove();}const items=[...cards.children];items.sort((a,b)=>(b.dataset.pinned==='true')-(a.dataset.pinned==='true')||(b.dataset.newsDate||'').localeCompare(a.dataset.newsDate||''));for(const card of items)cards.append(card);}
setInterval(()=>document.querySelectorAll('#portalNewsCards,#staffNewsCards').forEach(sortAndPinStaffNews),60000);

async function refreshPortalUniverse(){if(!document.getElementById('portalPlanetCount'))return;try{const data=await portalRequest('worldstats');document.getElementById('portalPlanetCount').textContent=Number(data.planets).toLocaleString();document.getElementById('portalAsteroidCount').textContent=Number(data.asteroids).toLocaleString();document.getElementById('portalAllianceCount').textContent=Number(data.alliances).toLocaleString();document.getElementById('portalUniverseStatus').textContent='SHARED UNIVERSE · LIVE DATABASE';}catch(error){document.getElementById('portalUniverseStatus').textContent='Universe status temporarily unavailable.';}}refreshPortalUniverse();setInterval(refreshPortalUniverse,30000);

document.addEventListener('click',e=>{const link=e.target.closest('[data-footer-placeholder]');if(link){e.preventDefault();document.getElementById('portalFooterStatus').textContent=link.dataset.footerPlaceholder+' — coming soon.';}});
// Reuse this hover/focus/tap reveal pattern for future hidden content.
document.querySelectorAll('.race-reference-card').forEach(card=>{const button=card.querySelector('.race-expand');if(!button)return;const close=()=>{card.classList.remove('is-expanded');button.setAttribute('aria-expanded','false');};button.addEventListener('click',()=>{const open=true;document.querySelectorAll('.race-reference-card.is-expanded').forEach(other=>{other.classList.remove('is-expanded');other.querySelector('.race-expand').setAttribute('aria-expanded','false');});card.classList.toggle('is-expanded',open);button.setAttribute('aria-expanded',String(open));});button.addEventListener('mouseenter',()=>{card.classList.add('is-expanded');button.setAttribute('aria-expanded','true');});let closeTimer;card.addEventListener('mouseenter',()=>clearTimeout(closeTimer));card.addEventListener('mouseleave',()=>{closeTimer=setTimeout(close,200);});card.addEventListener('focusout',e=>{if(!card.contains(e.relatedTarget))close();});card.addEventListener('keydown',e=>{if(e.key==='Escape'){close();button.focus();}});});
(async()=>{const link=document.querySelector('[data-intel-dump]');if(!link)return;try{const response=await fetch('/api/alliance-intel',{credentials:'same-origin'});link.hidden=!response.ok;}catch{link.hidden=true;}})();
// Hidden discoveries share one hover, focus and touch pattern.
document.querySelectorAll('.secret-reveal').forEach(box=>{box.addEventListener('click',e=>{if(e.target===box||e.target.classList.contains('secret-marker'))box.classList.toggle('is-revealed');});box.addEventListener('mouseleave',()=>box.classList.remove('is-revealed'));box.addEventListener('keydown',e=>{if(e.key==='Escape')box.classList.remove('is-revealed');});});
