const rotatePortal=document.getElementById('rotatePortalThemes');if(rotatePortal){rotatePortal.checked=(sessionStorage.getItem('starfall-rotate-portal-themes')||(localStorage.getItem('starfall-remember-theme')!=='false'?localStorage.getItem('starfall-rotate-portal-themes'):null))==='true';rotatePortal.addEventListener('change',()=>{sessionStorage.setItem('starfall-rotate-portal-themes',String(rotatePortal.checked));if(localStorage.getItem('starfall-remember-theme')!=='false')localStorage.setItem('starfall-rotate-portal-themes',String(rotatePortal.checked));else localStorage.removeItem('starfall-rotate-portal-themes');location.hash='themes';location.reload();});}if(rememberTheme)rememberTheme.addEventListener('change',()=>{if(rememberTheme.checked)localStorage.setItem('starfall-rotate-portal-themes',sessionStorage.getItem('starfall-rotate-portal-themes')||'false');else localStorage.removeItem('starfall-rotate-portal-themes');});
async function portalAllianceRequest(body){return portalRequest('alliance-manager',body);}
async function loadPortalAllianceManager(){const root=document.getElementById('portalAllianceManager');if(!root)return;try{const data=await portalAllianceRequest(),directory=await portalRequestDirectoryRevision();const fields=(a,prefix)=>'<div class="profile-alliance-fields">'+[['name','Alliance name'],['tag','Tag'],['description','Description'],['recruitmentMessage','Recruitment message'],['motd','MOTD']].map(([key,label])=>'<label>'+label+(key==='name'||key==='tag'?'<input id="'+prefix+'-'+key+'" value="'+portalEscape(a[key]||'')+'" maxlength="'+(key==='name'?40:8)+'">':'<textarea id="'+prefix+'-'+key+'" maxlength="2000" rows="3">'+portalEscape(a[key]||'')+'</textarea>')+'</label>').join('')+'</div>';const card=(a,active=false)=>{const id=active?'active':a.id,canEdit=active?a.canEdit:a.status!=='Active'&&a.canEdit,status=active?'Active':a.status;return '<article class="profile-theme-box portal-alliance-card" data-manager-id="'+portalEscape(a.id||'')+'" data-manager-prefix="'+id+'" data-manager-revision="'+directory+'"><div class="section-bar"><b>'+portalEscape(a.name)+'</b><span>'+status+'</span></div><p>'+(active?'Current round alliance · rank '+portalEscape(a.rank):'Registered alliance and your personal key')+'</p>'+(canEdit?fields(a,id)+'<button class="button" data-alliance-manager-action="update">SAVE ALLIANCE SETTINGS</button>':'<p>Only an Owner can edit alliance settings.</p>')+(!active&&status!=='Revoked'?'<div class="portal-key-controls"><button class="button secondary" data-alliance-manager-action="key">SHOW MY KEY</button><input readonly type="text" data-manager-secret placeholder="Personal key hidden"><label>My disclosure passphrase<input type="password" data-manager-phrase autocomplete="new-password" minlength="12" maxlength="128"></label><button class="button secondary" data-alliance-manager-action="phrase">SET MY PASSPHRASE</button><button class="button secondary" data-alliance-manager-action="rotate">ROTATE MY KEY</button>'+(status==='Reserved'||status==='Archived'?'<button class="button" data-alliance-manager-action="activate">ACTIVATE IN CURRENT ROUND</button>':'')+'</div>':'')+((active&&a.canEdit)||a.status!=='Active'&&a.canAddHolders?'<div class="portal-holder-controls"><h3>Add a keyholder</h3><p>Up to two additional holders. For an active alliance the account must already be a member and becomes an Owner. Each holder sees only their personal key.</p><label>Account username<input data-manager-holder autocomplete="off" maxlength="32"></label><button class="button secondary" data-alliance-manager-action="addHolder">ADD KEYHOLDER</button></div>':'')+'</article>';};root.innerHTML='<section class="profile-theme-box"><div class="section-bar"><b>INACTIVE ALLIANCE RESERVATIONS</b><span>'+data.reservedCount+' / '+data.limit+'</span></div><p>Reserving an alliance does not join it or change your active round alliance.</p>'+fields({},'reserve')+'<label>Optional disclosure passphrase<input id="reserve-phrase" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label><button class="button" data-alliance-manager-reserve '+(data.reservedCount>=data.limit?'disabled':'')+'>RESERVE ALLIANCE & GENERATE MY KEY</button></section>'+(data.active?'<h3>Current active alliance</h3>'+card(data.active,true):'<p>You currently have no active alliance.</p>')+'<h3>My registered alliances & keys</h3>'+data.alliances.map(a=>card(a)).join('')+'<p id="portalAllianceManagerStatus" class="status" role="status"></p>';}catch(error){root.textContent=error.message;}}
function portalEscape(text){return String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function portalRequestDirectoryRevision(){const response=await fetch('/api/planets',{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Cannot load current round.');return data.revision;}
function managerFields(prefix){return Object.fromEntries(['name','tag','description','recruitmentMessage','motd'].map(k=>[k,document.getElementById(prefix+'-'+k)?.value||'']));}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-profile-tab="alliances"]');if(tab)loadPortalAllianceManager();const reserve=e.target.closest('[data-alliance-manager-reserve]'),button=e.target.closest('[data-alliance-manager-action]');if(!reserve&&!button)return;const status=document.getElementById('portalAllianceManagerStatus');try{if(reserve){reserve.disabled=true;await portalAllianceRequest({action:'reserve',...managerFields('reserve'),passphrase:document.getElementById('reserve-phrase').value||undefined});await loadPortalAllianceManager();document.getElementById('portalAllianceManagerStatus').textContent='Alliance reserved and your personal encrypted key generated.';return;}const card=button.closest('[data-manager-id]'),action=button.dataset.allianceManagerAction,body={action,id:card.dataset.managerId,revision:Number(card.dataset.managerRevision)};if(action==='update')Object.assign(body,managerFields(card.dataset.managerPrefix));if(action==='addHolder')body.username=card.querySelector('[data-manager-holder]').value;if(['phrase','rotate'].includes(action))body.passphrase=card.querySelector('[data-manager-phrase]').value;if(action==='rotate'&&!confirm('Rotate your personal key? Its old key and disclosure passphrase will stop working.'))return;if(action==='activate'&&!confirm('Activate this alliance in the current round and leave your current alliance?'))return;button.disabled=true;const result=await portalAllianceRequest(body);if(action==='key'){const field=card.querySelector('[data-manager-secret]');field.value=result.secret;setTimeout(()=>{field.value='';},60000);button.disabled=false;return;}await loadPortalAllianceManager();document.getElementById('portalAllianceManagerStatus').textContent=action==='activate'?'Alliance activated. You are its Owner.':'Alliance manager updated.';}catch(error){if(status)status.textContent=error.message;if(reserve)reserve.disabled=false;if(button)button.disabled=false;}});
if(location.hash==='#alliances'&&document.getElementById('portalAllianceManager')){document.querySelectorAll('[data-profile-panel]').forEach(panel=>panel.hidden=panel.dataset.profilePanel!=='alliances');loadPortalAllianceManager();}
function portalRankName(role){return {player:'Player',support:'Support',multihunter:'Multihunter',admin:'Administrator'}[role]||role;}
function applyPortalStaffPermissions(){const nodes={control:'adminControl',alliances:'allianceAdmin',multihunters:'multihunter',users:'accounts',ranks:'ranks',audit:'audit',news:'siteManagement',tickets:'support'};for(const b of document.querySelectorAll('[data-staff-tab]'))b.hidden=b.dataset.staffTab==='round'?false:b.dataset.staffTab==='control'?!(staffCan('adminControl')||staffCan('bank')):b.dataset.staffTab==='news'?!(staffCan('siteManagement')||staffCan('news')):!staffCan(nodes[b.dataset.staffTab]);for(const a of document.querySelectorAll('a[href="/diagnostics.html"]'))a.hidden=!staffCan('diagnostics');const legacy=document.getElementById('staffLegacyToggle');if(legacy&&!staffCan('adminControl'))legacy.closest('.profile-theme-box').hidden=true;const editor=document.getElementById('staffArticleForm');if(editor)editor.hidden=!staffCan('news');}

async function loadPortalAccountRanks(){const root=document.getElementById('portalAccountRanks');if(!root||!staffCan('ranks'))return;try{const response=await fetch('/api/admin/account-ranks',{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Ranks unavailable.');root.innerHTML=staffPermissionMatrixHTML(data)+'<div class="profile-alliance-fields">'+data.ranks.map(r=>'<article class="profile-theme-box"><h3>'+portalEscape(r.name)+'</h3><p>'+portalEscape(r.permissions)+'</p></article>').join('')+'</div><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>Current rank</th><th>Assign rank</th><th>Save</th></tr></thead><tbody>'+data.users.map(user=>'<tr><td>'+portalEscape(user.username)+'</td><td>'+portalEscape(portalRankName(user.role))+'</td><td><select id="portal-rank-'+portalEscape(user.id)+'">'+data.ranks.map(r=>'<option value="'+r.id+'" '+(r.id===user.role?'selected':'')+'>'+r.name+'</option>').join('')+'</select></td><td><button class="button secondary" data-save-portal-rank="'+portalEscape(user.id)+'">SAVE RANK</button></td></tr>').join('')+'</tbody></table></div><p id="portalRankStatus" role="status"></p>';}catch(error){root.textContent=error.message;}}
document.addEventListener('click',async e=>{if(e.target.closest('[data-staff-tab="ranks"]'))loadPortalAccountRanks();const button=e.target.closest('[data-save-portal-rank]');if(button&&staffCan('ranks')){try{button.disabled=true;const response=await fetch('/api/admin/account-ranks',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:button.dataset.savePortalRank,rank:document.getElementById('portal-rank-'+button.dataset.savePortalRank).value})}),data=await response.json();if(!response.ok)throw Error(data.error||'Rank update failed.');await loadPortalAccountRanks();document.getElementById('portalRankStatus').textContent='Account rank saved. Permissions apply on the next request.';}catch(error){button.disabled=false;document.getElementById('portalRankStatus').textContent=error.message;}}});
let staffAuditOffset=0;
async function loadStaffPlanetAudit(){const root=document.getElementById('staffPlanetAudit');if(!root||!window.isPortalStaff)return;try{const actor=document.getElementById('auditActor')?.value||'',planet=document.getElementById('auditPlanet')?.value||'',query=new URLSearchParams({actor,planet,offset:String(staffAuditOffset)}),response=await fetch('/api/admin/planet-audit?'+query,{credentials:'same-origin'}),data=await response.json();if(!response.ok)throw Error(data.error||'Audit unavailable.');root.innerHTML='<form id="staffAuditFilters" class="profile-alliance-fields"><label>Staff account<input id="auditActor" value="'+portalEscape(actor)+'" placeholder="Filter by staff username"></label><label>Planet or coordinates<input id="auditPlanet" value="'+portalEscape(planet)+'" placeholder="Filter by planet or coordinates"></label><button class="button" type="submit">FILTER EDITS</button></form><div class="staff-audit-cards">'+data.records.map(record=>'<article class="profile-theme-box staff-audit-card"><div class="section-bar"><b>'+portalEscape(record.planet_name)+' · '+portalEscape(record.coords)+'</b><span>'+new Date(record.created_at).toLocaleString()+'</span></div><p><b>'+portalEscape(record.actor_name)+'</b> · '+portalEscape(record.action)+' · '+record.changes.fields.length+' changes</p><details><summary>VIEW CHANGED FIELDS</summary><div class="table-wrap"><table class="table"><thead><tr><th>Field</th><th>Previous value</th><th>New value</th></tr></thead><tbody>'+record.changes.fields.map(change=>'<tr><td>'+portalEscape(change.field)+'</td><td>'+portalEscape(change.old)+'</td><td>'+portalEscape(change.new)+'</td></tr>').join('')+'</tbody></table></div>'+(record.changes.truncated?'<p>First 300 fields shown for this large edit.</p>':'')+'</details></article>').join('')+(data.records.length?'':'<p>No staff planet edits match these filters.</p>')+'</div><div class="actions">'+(staffAuditOffset?'<button class="button secondary" data-staff-audit-offset="'+Math.max(0,staffAuditOffset-25)+'">NEWER</button>':'')+(data.hasMore?'<button class="button secondary" data-staff-audit-offset="'+data.nextOffset+'">OLDER</button>':'')+'</div>';}catch(error){root.textContent=error.message;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-staff-tab="audit"]'))loadStaffPlanetAudit();const page=e.target.closest('[data-staff-audit-offset]');if(page){staffAuditOffset=Number(page.dataset.staffAuditOffset);loadStaffPlanetAudit();}});
document.addEventListener('submit',e=>{if(e.target.id==='staffAuditFilters'){e.preventDefault();staffAuditOffset=0;loadStaffPlanetAudit();}});

(()=>{const search=document.getElementById('manualSearch'),home=document.getElementById('manual-home');if(!search||!home)return;const chapters=[...document.querySelectorAll('.manual-chapter')],links=[...document.querySelectorAll('[data-manual-link]')],results=document.getElementById('manualSearchResults'),status=document.getElementById('manualSearchStatus');function showChapter(){const hash=decodeURIComponent(location.hash.slice(1)),target=document.getElementById(hash),chapter=target?.closest('.manual-chapter'),query=search.value.trim().toLowerCase();if(query){const words=query.split(/\s+/),found=chapters.filter(c=>words.every(w=>c.textContent.toLowerCase().includes(w)));home.hidden=true;chapters.forEach(c=>c.hidden=true);results.hidden=false;results.replaceChildren();const heading=document.createElement('h2');heading.textContent=found.length+' matching chapters';results.append(heading);if(!found.length){const text=document.createElement('p');text.textContent='No matching chapters. Try fewer words or another spelling.';results.append(text);}for(const c of found){const card=document.createElement('article');card.className='manual-search-hit';const link=document.createElement('a');link.href='#'+c.id;link.textContent=c.dataset.chapterTitle;link.addEventListener('click',()=>{search.value='';showChapter();});const excerpt=document.createElement('p');excerpt.textContent=c.querySelector('.manual-subsection')?.textContent.trim().slice(0,220)||'';card.append(link,excerpt);results.append(card);}status.textContent=found.length+' of '+chapters.length+' chapters';links.forEach(l=>l.hidden=!found.some(c=>c.id===l.dataset.manualLink));}else{results.hidden=true;home.hidden=!!chapter;chapters.forEach(c=>c.hidden=c!==chapter);links.forEach(l=>{l.hidden=false;if(l.dataset.manualLink===chapter?.id)l.setAttribute('aria-current','page');else l.removeAttribute('aria-current');});status.textContent=chapter?chapter.dataset.chapterTitle:chapters.length+' chapters · choose a topic';}document.querySelectorAll('.manual-nav-group').forEach(g=>g.hidden=![...g.querySelectorAll('a')].some(l=>!l.hidden));}search.addEventListener('input',showChapter);document.getElementById('manualClearSearch').addEventListener('click',()=>{search.value='';showChapter();search.focus();});document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&document.getElementById(a.getAttribute('href').slice(1))){search.value='';showChapter();}});window.addEventListener('hashchange',()=>{showChapter();const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target&&!target.hidden)target.scrollIntoView({block:'start'});});showChapter();})();

function refreshNewsArchivePagination(){const archive=document.querySelector('.news-archive');if(!archive)return;const staff=document.getElementById('staffNewsCards'),articles=[...(staff?.querySelectorAll(':scope > article')||[]),...archive.querySelectorAll(':scope > article')].sort((a,b)=>{const date=e=>Date.parse(e.dataset.newsDate||e.querySelector('time')?.dateTime||'')||0;return date(b)-date(a);});const pages=Math.max(1,Math.ceil(articles.length/20));let page=Math.max(1,Math.min(pages,Number(new URLSearchParams(location.search).get('page'))||1));page=Math.trunc(page);articles.forEach((a,i)=>a.hidden=i<(page-1)*20||i>=page*20);const staffSection=document.getElementById('staffPublishedNews');if(staffSection)staffSection.hidden=![...(staff?.children||[])].some(a=>!a.hidden);let pagers=[...document.querySelectorAll('.news-pagination')];if(!pagers.length){for(const position of ['before','after']){const nav=document.createElement('nav');nav.className='news-pagination';nav.setAttribute('aria-label','News archive pagination');position==='before'?archive.before(nav):archive.after(nav);}pagers=[...document.querySelectorAll('.news-pagination')];}for(const nav of pagers){nav.replaceChildren();const status=document.createElement('span');status.className='news-page-status';status.textContent=articles.length?((page-1)*20+1)+'–'+Math.min(page*20,articles.length)+' of '+articles.length+' articles · Page '+page+' of '+pages:'No articles';nav.append(status);const button=(label,target,disabled,current=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;if(current)b.setAttribute('aria-current','page');b.addEventListener('click',()=>{const url=new URL(location.href);url.searchParams.set('page',target);history.replaceState(null,'',url);refreshNewsArchivePagination();document.querySelector('.news-pagination').scrollIntoView({block:'start'});});nav.append(b);};button('← Previous',page-1,page===1);for(let n=1;n<=pages;n++)if(n===1||n===pages||Math.abs(n-page)<=2)button(String(n),n,false,n===page);button('Next →',page+1,page===pages);}}
refreshNewsArchivePagination();window.addEventListener('popstate',refreshNewsArchivePagination);

function staffPermissionMatrixHTML(data){return '<section class="profile-theme-box"><h2>Staff permission nodes</h2><p>Changes apply on the next request. Administrator access is fixed; Player accounts receive no staff permissions. Owner-key reveal requires Alliance Controlcenter. Admin Controlcenter also grants advanced directory, reserve and structure editing.</p><div class="table-wrap"><table class="table"><thead><tr><th>Permission / responsibility</th>'+data.ranks.filter(r=>r.id!=='player').map(r=>'<th>'+portalEscape(r.name)+'</th>').join('')+'</tr></thead><tbody>'+data.nodes.map(n=>'<tr><td><b>'+portalEscape(n.name)+'</b><small style="display:block;max-width:480px">'+portalEscape(n.description)+'</small></td>'+data.ranks.filter(r=>r.id!=='player').map(r=>'<td><input type="checkbox" data-staff-node="'+n.id+'" data-staff-role="'+r.id+'" aria-label="'+portalEscape(r.name+' · '+n.name)+'" '+(r.nodes[n.id]?'checked ':'')+(!data.canEditPermissions||r.id==='admin'?'disabled':'')+'></td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="controls">'+data.ranks.filter(r=>['support','multihunter'].includes(r.id)).map(r=>'<button class="button secondary" data-save-staff-nodes="'+r.id+'" data-revision="'+r.revision+'" '+(!data.canEditPermissions?'disabled':'')+'>SAVE '+portalEscape(r.name.toUpperCase())+' PERMISSIONS</button>').join('')+'</div><p id="staffNodesStatus" role="status"></p></section>';}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-save-staff-nodes]');if(!b||!window.isAccountAdministrator)return;const role=b.dataset.saveStaffNodes,permissions=Object.fromEntries([...document.querySelectorAll('[data-staff-role="'+role+'"]')].map(i=>[i.dataset.staffNode,i.checked])),status=document.getElementById('staffNodesStatus');if(permissions.keyReveal&&!permissions.allianceAdmin){status.textContent='Owner-key reveal also requires Alliance Controlcenter.';return;}b.disabled=true;try{const response=await fetch('/api/admin/account-ranks',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'permissions',role,revision:Number(b.dataset.revision),permissions})}),d=await response.json();if(!response.ok)throw Error(d.error||'Permissions could not be saved.');await loadPortalAccountRanks();document.getElementById('staffNodesStatus').textContent='Permissions saved and audited. They apply on the next request.';}catch(error){status.textContent=error.message;b.disabled=false;}});


