(()=>{'use strict';const game=['/game','/game/','/index.html'].includes(location.pathname),audio=new Audio('/assets/media/vesper-desert-score.mp3?v=0.97.0');audio.hidden=true;audio.preload='none';document.body.append(audio);audio.loop=true;audio.volume=.22;let enabled=false,toolbar,videoPlaying=false;try{if(!game)enabled=localStorage.getItem('starfall-portal-music-enabled')==='true';}catch{}
function wanted(){return game?typeof state!=='undefined'&&!!state.userSettings.gameAmbientMusic:enabled;}
function status(message){const el=document.getElementById(game?'gameMusicStatus':'portalMusicStatus');if(el)el.textContent=message;const button=document.getElementById('portalMusicToggle');if(button){button.textContent=wanted()?'MUTE MUSIC':'ENABLE MUSIC';button.setAttribute('aria-pressed',String(wanted()));}}
async function apply(){if(!wanted()||videoPlaying){audio.pause();status(!wanted()?'Music off':'Music paused while video plays');return;}try{await audio.play();status('Vesper desert score · playing');}catch{status('Music ready · starts after your next click');}}
window.applyAmbientMusic=apply;
if(!game){toolbar=document.createElement('div');toolbar.className='portal-music-toolbar';toolbar.innerHTML='<span id="portalMusicStatus" role="status">Original cinematic ambience</span><button id="portalMusicToggle" class="button secondary" type="button">MUTE MUSIC</button><label for="portalMusicVolume">Volume <input id="portalMusicVolume" type="range" min="0" max="100" value="22"></label>';const settings=document.querySelector('.profile-theme-section');if(settings){toolbar.classList.add('profile-theme-box');settings.append(toolbar);}else{toolbar.hidden=true;document.body.append(toolbar);}document.getElementById('portalMusicToggle').addEventListener('click',()=>{enabled=!enabled;try{localStorage.setItem('starfall-portal-music-enabled',String(enabled));}catch{}apply();});document.getElementById('portalMusicVolume').addEventListener('input',e=>audio.volume=Number(e.target.value)/100);}
document.addEventListener('pointerdown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('keydown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO'){videoPlaying=true;apply();}},true);for(const event of ['pause','ended'])document.addEventListener(event,e=>{if(e.target.tagName==='VIDEO'){videoPlaying=[...document.querySelectorAll('video')].some(v=>!v.paused&&!v.ended);apply();}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause();else apply();});apply();})();


// display-names.js
'use strict';
// Display names stay separate from stable saved race/theme identifiers.
const RACE_DISPLAY_NAMES={Terran:'Helion',Cathaar:'Velari',Xandathrii:'Nexari',Zikonian:'Kryth',Eitraides:'Auralis'};
const THEME_DISPLAY_NAMES={Classic:'Classic',NyanCat:'Nyan Cat',Neutral:'Vesper Command',Terran:'Helion Ascendancy',Cathaar:'Velari Ember',Xandathrii:'Nexari Swarm',Zikonian:'Kryth Frost',Eitraides:'Auralis Tide',LCARS:'Stellar Federation',Borg:'Assimilation Nexus',Stargate:'Gatebound Legacy',DoctorWho:'Temporal Voyager',Battlestar:'Colonial Vanguard'};
function renamedDisplayText(value){let result=String(value).replace(/\b(?:Current )?Round setup\b/gi,'Current Round Setup').replace(/\bRound stats\b/gi,'Stats Editor').replace(/Neutral · COMMAND SKIN/g,'Vesper Command · COMMAND SKIN').replace(/Administration → Planets/g,'Administration → Planet Editor').replace(/Administration → Ship Stats/g,'Administration → Stats Editor');for(const [oldName,name] of Object.entries({'Neutral sci-fi':'Vesper Command','Star Trek LCARS':'Stellar Federation','Star Trek Borg':'Assimilation Nexus','Battlestar Galactica':'Colonial Vanguard','Doctor Who':'Temporal Voyager',Stargate:'Gatebound Legacy','the Miday array':'Satelite Uplink','The Miday array':'Satelite Uplink','Miday array':'Satelite Uplink','Miday Array':'Satelite Uplink','Miday':'Satelite Uplink','Galaxy Status':'Network Hub','Galaxy status':'Network Hub','galaxy status':'network hub','News log':'Journal','News Log':'Journal','news log':'journal',Quests:'Achievements',quests:'achievements',Quest:'Achievement',quest:'achievement',...RACE_DISPLAY_NAMES})){result=result.replace(new RegExp('\\b'+oldName+'\\b','g'),name).replace(new RegExp('\\b'+oldName.toUpperCase()+'\\b','g'),name.toUpperCase());}return result;}
function coordinateDisplayText(value){if(/\d{1,4}[\/-]\d{1,2}[\/-]\d{1,4}/.test(value))return value;return String(value).replace(/\b(\d{1,3})\s*:\s*(\d{1,3})\s*:\s*(\d{1,2})\b/g,(raw,x,y,z)=>Number(x)>=1&&Number(x)<=100&&Number(y)>=1&&Number(y)<=100&&Number(z)>=1&&Number(z)<=15?[x,y,z].map(Number).join(':'):raw).replace(/(GALAXY\s+)(\d{1,3})\s*:\s*(\d{1,3})/gi,(_,label,x,y)=>label+Number(x)+':'+Number(y));}
function applyDisplayNames(root){if(root.nodeType===3){const admin=root.parentElement?.closest('button[data-page="adminPlanets"],button[data-page="adminShips"]');if(admin){const label=admin.dataset.page==='adminPlanets'?'Planet Editor':'Stats Editor';if(root.nodeValue.trim()&&root.parentElement.tagName!=='EM'){if(root.nodeValue!==label)root.nodeValue=label;return;}}if(root.parentElement?.tagName==='OPTION'){applyDisplayNames(root.parentElement);return;}if(!root.parentElement?.closest('script,style,textarea,code,input')){const renamed=renamedDisplayText(root.nodeValue),updated=root.parentElement?.closest('time,.command-time-box,.tickbox,#militaryClock,#serverMilitaryClock')?renamed:coordinateDisplayText(renamed);if(updated!==root.nodeValue)root.nodeValue=updated;}return;}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1){if(root.tagName==='OPTION'){if(!root.hasAttribute('value'))root.setAttribute('value',root.value);const key=root.value,theme=['portalTheme','profileTheme','skinRaceSelect'].includes(root.parentElement?.id),label=theme?THEME_DISPLAY_NAMES[key]:RACE_DISPLAY_NAMES[key];if(label&&root.textContent!==label)root.textContent=label;else if(!label){const display=coordinateDisplayText(root.textContent);if(display!==root.textContent)root.textContent=display;}return;}if(root.matches('script,style,textarea,code,input'))return;for(const attr of ['alt','title','aria-label'])if(root.hasAttribute(attr)){const old=root.getAttribute(attr),updated=renamedDisplayText(old);if(old!==updated)root.setAttribute(attr,updated);}}for(const child of root.childNodes)applyDisplayNames(child);}
function startDisplayNames(){applyDisplayNames(document.body);new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')applyDisplayNames(record.target);else for(const node of record.addedNodes)applyDisplayNames(node);}}).observe(document.body,{childList:true,subtree:true,characterData:true});document.title=renamedDisplayText(document.title);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startDisplayNames);else startDisplayNames();


// fleet-look.js
const TREK_POWERS=['Federation','Klingon','Romulan','Cardassian','Dominion','Borg','Ferengi','Breen'];
const TREK_NAMES={Federation:['USS Defiant','USS Voyager','USS Enterprise NX-01','USS Enterprise NCC-1701','USS Enterprise-A','USS Enterprise-D','USS Enterprise-E','USS Discovery','USS Titan-A','USS Enterprise-G'],Klingon:['IKS Bounty','IKS Pagh','IKS Rotarran','IKS Ch’Tang','IKS Hegh’ta','IKS Negh’Var','IKS Bortas','IKS T’Ong','IKS Koraga','IKS Sarcophagus'],Romulan:['IRW Khazara','IRW T’Met','IRW Devoras','IRW Haakona','IRW Terix','IRW Valdore','IRW Scimitar','IRW Narada','IRW D’Deridex','IRW Tal Shiar'],Cardassian:['CDS Prakesh','CDS Trager','CDS Vetar','CDS Reklar','CDS Aldara','CDS Kraxon','CDS Galor','CDS Keldon','CDS Bok’Nor','CDS Ravinok'],Dominion:['Jem’Hadar Vanguard','Jem’Hadar Interceptor','Jem’Hadar Strike Wing','Jem’Hadar Escort','Jem’Hadar Attack Ship','Jem’Hadar Battlecruiser','Jem’Hadar Dreadnought','Founder’s Will','Vorta Command','Dominion Flagship'],Borg:['Probe Alpha','Sphere One','Tactical Cube','Assimilation Cube','Queen’s Vessel','Unimatrix One','Diamond Command','Collective Vanguard','Cube 001','Nexus Prime'],Ferengi:['Kreechta','Krayton','D’Kora','Marauder Profit','Grand Nagus','Divine Treasury','Latinum Venture','Commerce Raider','Acquisition Prime','Fortune’s Edge'],Breen:['Gor’s Command','Thot’s Spear','Chel Grett','Rezreth','Sarr Theln','Absolute Zero','Cold Dominion','Polar Vanguard','Cryonic Blade','Breen Flagship']};

function applyReferenceFleetLook(){let settings={};try{settings=JSON.parse(localStorage.getItem('starfall-round-v2')||'{}').userSettings||{};}catch{}document.querySelectorAll('.stat-ship-name').forEach((row,index)=>{const image=row.querySelector('img'),label=row.querySelector('span');if(!image||!label)return;if(!row.dataset.originalName){row.dataset.originalName=label.textContent;row.dataset.originalAlt=image.alt;}let art=row.querySelector('.reference-trek-art');if(!settings.trekFleetEnabled){image.hidden=false;if(art)art.remove();label.textContent=row.dataset.originalName;label.classList.remove('reference-hero-name');return;}const race=row.closest('[data-stat-race]')?.dataset.statRace,power=TREK_POWERS.includes(settings.trekFleetPower)?settings.trekFleetPower:({Terran:'Federation',Cathaar:'Klingon',Xandathrii:'Romulan',Zikonian:'Cardassian',Eitraides:'Dominion'})[race]||'Federation',column=TREK_POWERS.indexOf(power),cls=row.closest('tr')?.querySelector('td')?.textContent,level=Math.min(4,['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'].indexOf(cls));image.hidden=true;if(!art){art=document.createElement('span');art.className='reference-trek-art';row.prepend(art);}art.style.backgroundPosition=(column*100/7)+'% '+(Math.max(0,level)*20)+'%';const relativeIndex=[...row.closest('[data-stat-race]').querySelectorAll('.stat-ship-name')].indexOf(row);label.textContent=TREK_NAMES[power][relativeIndex%10]+' ★ '+power.slice(0,3).toUpperCase()+'-'+String(index+1).padStart(3,'0');label.classList.add('reference-hero-name');});}applyReferenceFleetLook();window.addEventListener('storage',applyReferenceFleetLook);


// staff-roster.js
async function renderStaffRoster(){const root=document.getElementById('portalStaffDirectory')||document.querySelector('[data-staff-section="round"]');if(!root)return;let roster=document.getElementById('staffRoster');if(!roster){roster=document.createElement('section');roster.id='staffRoster';root.append(roster);}try{const r=await fetch(document.getElementById('portalStaffDirectory')?'/api/staff-directory':'/api/portal/staff-roster',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.error||'Roster unavailable.');roster.replaceChildren();const header=document.createElement('div');header.className='staff-roster-heading';const h=document.createElement('h3'),p=document.createElement('p');h.textContent='Command personnel';p.textContent=d.staff.length+' staff members · Official responsibilities · Read-only account registry';header.append(h,p);roster.append(header);const grid=document.createElement('div');grid.className='staff-roster-grid';for(const member of d.staff){const card=document.createElement('article');card.className='staff-personnel-card';card.dataset.role=member.role;const seal=document.createElement('span');seal.className='staff-personnel-seal';seal.textContent={admin:'✦',support:'✉',multihunter:'⌕'}[member.role];const body=document.createElement('div'),title=document.createElement('small'),name=document.createElement('h4'),id=document.createElement('span'),desc=document.createElement('p');title.textContent=member.title;name.textContent=member.username;id.className='staff-personnel-id';id.textContent='ACCOUNT ID '+member.accountId;desc.textContent=member.description;body.append(title,name,id,desc);card.append(seal,body);grid.append(card);}roster.append(grid);}catch(e){roster.textContent=e.message;}}
document.addEventListener('starfall-session-ready',renderStaffRoster);setTimeout(renderStaffRoster,1000);


// site-management.js
let siteFeatureSettings=null;async function loadSiteFeatures(){if(document.hidden)return;try{const r=await fetch('/api/site-management',{credentials:'same-origin'});if(!r.ok)return;const d=await r.json();siteFeatureSettings=d;if(typeof state!=='undefined'){state.siteManagement={roundHistoryDemo:d.roundHistoryDemo,battleCalcTest:d.battleCalcTest};const lab=document.getElementById('uplinkTestLab');if(lab)lab.hidden=!d.battleCalcTest;}const panel=document.querySelector('[data-staff-section="news"]');if(panel&&d.canEdit&&!document.getElementById('siteTestFeatures')){const module=document.createElement('section');module.id='siteTestFeatures';module.className='profile-theme-box';module.innerHTML='<h3>Site test features</h3><p>These switches apply to the entire site. Real archived rounds always replace demonstration rounds.</p><label><input id="historyDemoEnabled" type="checkbox" '+(d.roundHistoryDemo?'checked':'')+'> Show fictional Round history examples while the real archive is empty</label><label><input id="battleTestEnabled" type="checkbox" '+(d.battleCalcTest?'checked':'')+'> Enable the simulated battle lab and battle calculator test</label><button class="button" id="saveSiteTestFeatures">SAVE SITE FEATURES</button><p id="siteFeatureStatus" role="status"></p>';panel.prepend(module);document.getElementById('saveSiteTestFeatures').onclick=saveSiteFeatures;}}catch{}}
async function saveSiteFeatures(){const status=document.getElementById('siteFeatureStatus');try{const r=await fetch('/api/site-management',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:siteFeatureSettings.revision,roundHistoryDemo:document.getElementById('historyDemoEnabled').checked,battleCalcTest:document.getElementById('battleTestEnabled').checked})}),d=await r.json();if(!r.ok)throw Error(d.error||'Save failed.');siteFeatureSettings.revision=d.revision;status.textContent='✓ Site features saved · '+new Date().toLocaleTimeString();}catch(e){status.textContent=e.message;}}
setTimeout(loadSiteFeatures,1000);setInterval(loadSiteFeatures,30000);

